const alert = $('Webhook - Recibir Alerta').first().json.body;
const threatInfo = alert.threat_intel || {};

const level = alert.severity === 'critical' ? 12 :
              alert.severity === 'high' ? 8 :
              alert.severity === 'medium' ? 4 :
              alert.severity === 'low' ? 2 : 1;

const ruleName = (alert.rule_name || 'unknown').replace(/"/g, '').replace(/'/g, '');
const description = (alert.description || 'No description').replace(/"/g, '').replace(/'/g, '').replace(/\n/g, ' ').replace(/[$\\]/g, '');
const srcip = alert.source_ip || '0.0.0.0';
const riskScore = alert.risk_score || 0;

// Formato RFC 3164: <PRI>timestamp hostname TAG: message
// TAG = N8NALERT (sin underscore) para que predecedor extraiga program_name
const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const now = new Date();
const pad2 = (n) => String(n).padStart(2, '0');
const ts = months[now.getMonth()] + ' ' + pad2(now.getDate()) + ' ' + pad2(now.getHours()) + ':' + pad2(now.getMinutes()) + ':' + pad2(now.getSeconds());

const syslogMsg = '<13>' + ts + ' n8n-workflow N8NALERT: rule=' + ruleName + ' level=' + level + ' srcip=' + srcip + ' score=' + riskScore + ' desc="' + description + '"';

// Single quotes para evitar que sh expanda $, `, etc. No hay ' en ruleName/description porque los limpiamos.
// El \\n se pasa literal a printf, que lo interpreta como newline.
// El TAG debe empezar en columna 0 seguido de : para que predecedor extraiga program_name
const command = "printf '" + syslogMsg + "\\n' | nc -u -w2 wazuh-manager 514";

return [{ json: {
  data_source: "n8n_workflow",
  command: command,
  syslog_message: syslogMsg,
  original_alert: alert
} }];
